Historical fixture generator (full source), executed from %TEMP%/r33b-worker-6f8a2921 against git-archive tree 2364d4e3. Vite's SSR loader is used only because that historical tree has TypeScript sources whose imports spell .js but no .js bridges; it resolves those historical imports without changing the archive.

```js
import { createHash } from "node:crypto";
import {
  mkdtempSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const GENERATING_SHA = "2364d4e3";
const PROJECT_ID = "r33b-historical-fixture";
const encoder = new TextEncoder();
const outputPath = process.argv[2];
const viteModulePath = process.argv[3];
if (outputPath === undefined) throw new Error("fixture output path required");
if (viteModulePath === undefined) throw new Error("Vite module path required");

const { createServer } = await import(pathToFileURL(viteModulePath).href);
const treeRoot = fileURLToPath(new URL("./tree/", import.meta.url));
const vite = await createServer({
  appType: "custom",
  logLevel: "error",
  root: treeRoot,
  server: { middlewareMode: true },
});

try {
  const store = await vite.ssrLoadModule("/packages/store/src/index.ts");
  const contracts = await vite.ssrLoadModule(
    "/packages/store/src/recovery-anchor-contracts.ts",
  );
  const {
    SqliteEventStore,
    installRecoveryAnchor,
  } = store;
  const {
    RECOVERY_ANCHOR_DATABASE_NAME,
    RECOVERY_ANCHOR_SLOT_MANIFEST_NAME,
    RECOVERY_ANCHOR_SLOTS_DIR_NAME,
  } = contracts;

  const sha256 = (bytes) => createHash("sha256").update(bytes).digest("hex");

  function restoredDatabaseBytes(label) {
    const directory = mkdtempSync(join(tmpdir(), `r33b-source-${label}-`));
    const path = join(directory, "restored.sqlite");
    SqliteEventStore.openForProject(path, PROJECT_ID).close();
    return readFileSync(path);
  }

  async function emit(label, artifacts) {
    const anchorRoot = mkdtempSync(join(tmpdir(), `r33b-anchor-${label}-`));
    const result = await installRecoveryAnchor({
      anchorRoot,
      generationDigest: "aa".repeat(32),
      incarnationRef: "1a".repeat(32),
      keyEpochRef: "4d".repeat(32),
      payload: {
        artifacts,
        databaseBytes: restoredDatabaseBytes(label),
      },
      preparedAt: "2026-08-11T09:00:00.000Z",
      projectId: PROJECT_ID,
      restoreCommandId: `restore-command-r33b-${label}`,
    });
    if (!result.ok) {
      throw new Error(`${result.layer}/${result.code}`);
    }
    const slotRoot = join(
      anchorRoot,
      RECOVERY_ANCHOR_SLOTS_DIR_NAME,
      result.anchor.currentSlot,
    );
    const manifestBytes = readFileSync(
      join(slotRoot, RECOVERY_ANCHOR_SLOT_MANIFEST_NAME),
    );
    const databaseBytes = readFileSync(
      join(slotRoot, RECOVERY_ANCHOR_DATABASE_NAME),
    );
    const manifest = JSON.parse(manifestBytes.toString("utf8"));
    return {
      databaseDigest: sha256(databaseBytes),
      manifest,
      manifestBytes,
    };
  }

  const artifact = await emit("artifact", [
    {
      bytes: encoder.encode("artifact-one"),
      logicalPath: "artifacts/one.bin",
    },
  ]);
  mkdirSync(dirname(outputPath), { recursive: true });
  writeFileSync(outputPath, artifact.manifestBytes);

  const databaseOnly = await emit("database-only", []);
  console.log(JSON.stringify({
    artifact: {
      databaseDigest: artifact.databaseDigest,
      databaseDigestMatches:
        artifact.databaseDigest === artifact.manifest.databaseDigest,
      fixtureSha256: sha256(artifact.manifestBytes),
      keys: Object.keys(artifact.manifest),
      payloadDigestCount: Object.keys(artifact.manifest.payloadDigests).length,
      slotManifestVersion: artifact.manifest.slotManifestVersion,
    },
    databaseOnly: {
      databaseDigest: databaseOnly.databaseDigest,
      databaseDigestMatches:
        databaseOnly.databaseDigest === databaseOnly.manifest.databaseDigest,
      keys: Object.keys(databaseOnly.manifest),
      payloadDigestCount:
        Object.keys(databaseOnly.manifest.payloadDigests).length,
      slotManifestVersion: databaseOnly.manifest.slotManifestVersion,
    },
    generatingSha: GENERATING_SHA,
  }));
} finally {
  await vite.close();
}

